{
  "status": "checkpoint-before-native-execution",
  "findings": [
    {
      "id": "UX-01",
      "title": "Same document does not identify the current asynchronous contribution",
      "status": "source-supported-hypothesis",
      "sources": [
        "CM_LINT"
      ],
      "consequence": "Tag contribution tasks with generation and monotonic document revision; compare at result application. Native doc guard already protects a different class of stale completion.",
      "test": "CM-2,CM-3,CM-4,CM-5"
    },
    {
      "id": "UX-02",
      "title": "Serialized text Undo is not complete semantic Undo",
      "status": "source-confirmed-native-pending",
      "sources": [
        "CM_COMMANDS",
        "CM_HISTORY_LOCAL"
      ],
      "consequence": "A restore capability declares text/selection/history/custom effects separately. Plugin-private effects need an explicit codec or a disclosed history reset.",
      "test": "CM-7"
    },
    {
      "id": "UX-03",
      "title": "State-field identity and explicit reset are a real compatibility boundary",
      "status": "source-confirmed-native-pending",
      "sources": [
        "CM_STATE",
        "CM_IDENTITY_INTENT"
      ],
      "consequence": "Retain compatible host-owned field identities; replacing a field or using its explicit init is a declared reset. Avoid regenerating all extension values on unrelated renders.",
      "test": "CM-1,CM-6"
    },
    {
      "id": "UX-04",
      "title": "Reload hooks do not establish a universal render transaction",
      "status": "pinned-source-confirmed",
      "sources": [
        "FLUTTER_BINDING",
        "FLUTTER_FRAMEWORK"
      ],
      "consequence": "Readiness and first useful render need independent observations; views tolerate candidate-not-ready state. Keep the critical input block narrow, expose it, and reuse framework invalidation."
    },
    {
      "id": "UX-05",
      "title": "A formally disposed resource can still have the wrong lifetime parent",
      "status": "documentation-confirmed",
      "sources": [
        "JB_DISPOSER",
        "JB_DYNAMIC"
      ],
      "consequence": "Use owner scopes no longer than the plugin contribution; report predecessor retention reasons rather than only disposal callback completion. Plugin service/dialog/tab lifetime beats application lifetime for plugin UI subscriptions."
    },
    {
      "id": "UX-06",
      "title": "Preview and cancellation must respect the owning reconfiguration phase",
      "status": "source-confirmed",
      "sources": [
        "JB_DYNAMIC_SOURCE",
        "JB_DYNAMIC"
      ],
      "consequence": "Preview affected dependency closure from the existing planner; don't mutate mode/state before feasibility. Pause applies to future candidate admission; a non-cancellable committed phase exposes wait/recovery, not a false cancel."
    },
    {
      "id": "UX-07",
      "title": "Restart scope is part of the user contract",
      "status": "documentation-and-source-confirmed",
      "sources": [
        "VSCODE_HOST",
        "VSCODE_RESTART",
        "ELECTRON_PORT"
      ],
      "consequence": "Show contribution restart, worker/host restart, renderer reload, or application restart explicitly, with dirty-state and resources affected. Reconnect is not proof the prior host stopped."
    },
    {
      "id": "UX-08",
      "title": "Observation must survive reconnect without becoming another authority",
      "status": "recommended-contract-from-standard",
      "sources": [
        "SSE_SPEC",
        "REACT_SNAPSHOT",
        "TANSTACK_REFRESH"
      ],
      "consequence": "Expose an immutable authoritative snapshot plus cursor; gaps or expired cursors trigger snapshot resync. UI keeps stale last-known content visibly stale, and sends mutating actions with expected plan/revision."
    },
    {
      "id": "UX-09",
      "title": "Reusable lifecycle notification is narrower than plugin lifecycle control",
      "status": "specification-confirmed",
      "sources": [
        "OPENFEATURE_EVENTS"
      ],
      "consequence": "Use optional OpenFeature for rollout intent when a product needs it; preserve provider-ready/stale/reconciling distinctions. Never translate a ready event into successful plugin cleanup or a flag reversal into state rollback."
    },
    {
      "id": "UX-10",
      "title": "OS IME, focus and view remount are separate qualification dimensions",
      "status": "unqualified-acceptance-requirement",
      "sources": [
        "CM_VIEW",
        "CM_CHANGELOG"
      ],
      "consequence": "Defer disruptive replacement during composition or use a qualified native editor reconfiguration path; preserve draft and selection. Synthetic composition events do not demonstrate a real platform IME.",
      "test": "Explicitly not qualified by this probe"
    }
  ]
}

